import copy, json, runpy, sys
from pathlib import Path
bundle = Path('/tmp/kk-save-review-74x5_c32')
sys.path.insert(0, str(bundle / 'candidate'))
import client
from store import Store, ReceiptUnavailable

def state(store):
    return {'preferences': copy.deepcopy(store.preferences), 'recovery': copy.deepcopy(store.recovery)}

def attempt(store, operation_id, color):
    try:
        return client.submit(store, 'w', operation_id, {'color': color})
    except ReceiptUnavailable as error:
        return {'error': str(error)}

for label, service_path in [('base', bundle / 'historical/service.py'), ('staged', bundle / 'candidate/service.py')]:
    client.save = runpy.run_path(str(service_path))['save']
    store = Store()
    store.fail_receipt_once = True
    steps = []
    for operation_id, color in [('op-1', 'blue'), ('op-1', 'red'), ('op-1', 'green'), ('op-2', 'yellow')]:
        result = attempt(store, operation_id, color)
        steps.append({'submitted': [operation_id, color], 'result': result, 'state': state(store)})
    replay_store = Store()
    attempt(replay_store, 'op-1', 'blue')
    replay_store.fail_receipt_once = True
    replay = attempt(replay_store, 'op-1', 'blue')
    print(json.dumps({'revision': label, 'lifecycle': steps, 'completed_replay_with_receipt_failure': replay}, indent=2))
PY"

